    "ja": "爻光専用：速度160以上は両出典が一致する下限のため同値で比較する。会心率はGame8のモチーフ光円錐装備時72%以上を厳選、GameWithの52〜62%を目標・妥協に対応させ、会心ダメージも同様にGameWithの145〜163%とGame8の140%以上を割り当てる。モチーフ光円錐・星魂2/6の速度上昇や愉悦ダメージ上昇は装備・戦闘中条件のため公開プロフィールへ加算しない。オーナメントはGameWithが海に沈んだルサカ ×2を挙げるが、愉悦編成全体へ会心ダメージを配る目的でGame8の千の星が集う街 ×2を採用する。",
